<script>import{page}from'$app/stores';$:invalid=$page.url.searchParams.get('invalid')==='1';$:next=$page.url.searchParams.get('next')||'/';</script>
<svelte:head><title>RTSP to ONVIF login</title></svelte:head><main><form method="POST" action="/login/session"><span>RTSP TO ONVIF</span><h1>Enter password</h1><p>Sign in to manage virtual ONVIF cameras.</p><input type="hidden" name="next" value={next}><label>Password<input name="password" type="password" required autofocus></label>{#if invalid}<small>Incorrect password. Please try again.</small>{/if}<button>Continue</button></form></main>
<style>:global(body){margin:0;background:#090d12;color:#edf1f5;font:14px system-ui}main{min-height:100vh;display:grid;place-items:center;padding:20px}form{width:min(390px,100%);display:grid;gap:15px;padding:30px;background:#111820;border:1px solid #293441;border-radius:16px}span{color:#da3;font-size:10px;font-weight:800;letter-spacing:.18em}h1,p{margin:0}p{color:#929eab}label{display:grid;gap:7px}input{padding:12px;background:#080c11;border:1px solid #34404d;border-radius:8px;color:white}button{padding:12px;border:0;border-radius:8px;background:#da3;color:#171306;font-weight:800}small{color:#ff8c99}</style>
